import{_ as s,o as n,c as a,i as e}from"./app.f62a0f99.js";const m=JSON.parse('{"title":"Coding\u914D\u7F6E\u4E0E\u4F7F\u7528\u5165\u95E8","description":"","frontmatter":{},"headers":[{"level":2,"title":"1.\u5B89\u88C5\u672C\u5730\u73AF\u5883","slug":"_1-\u5B89\u88C5\u672C\u5730\u73AF\u5883","link":"#_1-\u5B89\u88C5\u672C\u5730\u73AF\u5883","children":[]},{"level":2,"title":"2. \u4E0B\u8F7D Codex \u5BA2\u6237\u7AEF","slug":"_2-\u4E0B\u8F7D-codex-\u5BA2\u6237\u7AEF","link":"#_2-\u4E0B\u8F7D-codex-\u5BA2\u6237\u7AEF","children":[]},{"level":2,"title":"3. Codex \u9875\u9762\u4ECB\u7ECD","slug":"_3-codex-\u9875\u9762\u4ECB\u7ECD","link":"#_3-codex-\u9875\u9762\u4ECB\u7ECD","children":[]},{"level":2,"title":"4. \u6784\u5EFA\u81EA\u5DF1\u7684\u9879\u76EE","slug":"_4-\u6784\u5EFA\u81EA\u5DF1\u7684\u9879\u76EE","link":"#_4-\u6784\u5EFA\u81EA\u5DF1\u7684\u9879\u76EE","children":[]}],"relativePath":"pages/explore/share/Coding\u914D\u7F6E\u4E0E\u4F7F\u7528\u5165\u95E8.md","lastUpdated":1779095613000}'),l={name:"pages/explore/share/Coding\u914D\u7F6E\u4E0E\u4F7F\u7528\u5165\u95E8.md"},p=e(`<h1 id="coding\u914D\u7F6E\u4E0E\u4F7F\u7528\u5165\u95E8" tabindex="-1">Coding\u914D\u7F6E\u4E0E\u4F7F\u7528\u5165\u95E8 <a class="header-anchor" href="#coding\u914D\u7F6E\u4E0E\u4F7F\u7528\u5165\u95E8" aria-hidden="true">#</a></h1><blockquote><p>\u8BE5\u6559\u7A0B\u53EA\u9002\u7528\u4E8E Mac \u7535\u8111, \u4EC5\u505A\u7B80\u5355\u7684\u5F15\u5BFC\u4F7F\u7528.</p><p>\u6CE8\u610F: \u9700\u8981\u81EA\u5907 VPN \u624D\u80FD\u6B63\u5E38\u8BBF\u95EEGPT.</p></blockquote><h2 id="_1-\u5B89\u88C5\u672C\u5730\u73AF\u5883" tabindex="-1">1.\u5B89\u88C5\u672C\u5730\u73AF\u5883 <a class="header-anchor" href="#_1-\u5B89\u88C5\u672C\u5730\u73AF\u5883" aria-hidden="true">#</a></h2><p>\u6253\u5F00\u7535\u8111, \u4F7F\u7528 option + \u7A7A\u683C, \u5524\u8D77\u7535\u8111\u4E0A\u7684\u641C\u7D22\u6846, \u8F93\u5165&quot;\u7EC8\u7AEF&quot;, \u6253\u5F00\u8BE5\u8F6F\u4EF6, \u5728\u8F6F\u4EF6\u4E0A\u5206\u522B\u8F93\u5165\u4E0B\u9762\u547D\u4EE4(\u4E00\u6761\u4E00\u6761\u547D\u4EE4\u7684\u8F93\u5165, \u4E2D\u95F4\u9700\u8981\u7B49\u5F85\u4E0A\u4E00\u6761\u547D\u4EE4\u6267\u884C\u5B8C)</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki"><code><span class="line"><span style="color:#676E95;"># \u4E0B\u8F7D\u5E76\u5B89\u88C5 nvm\uFF1A</span></span>
<span class="line"><span style="color:#A6ACCD;">curl -o- https://raw.githubusercontent.com/nvm-sh/nvm/v0.40.3/install.sh </span><span style="color:#89DDFF;">|</span><span style="color:#A6ACCD;"> bash</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;"># \u4EE3\u66FF\u91CD\u542F shell</span></span>
<span class="line"><span style="color:#A6ACCD;">\\. </span><span style="color:#89DDFF;">&quot;$</span><span style="color:#A6ACCD;">HOME</span><span style="color:#C3E88D;">/.nvm/nvm.sh</span><span style="color:#89DDFF;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;"># \u4E0B\u8F7D\u5E76\u5B89\u88C5 Node.js\uFF1A</span></span>
<span class="line"><span style="color:#A6ACCD;">nvm install 24</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;"># \u9A8C\u8BC1 Node.js \u7248\u672C\uFF1A</span></span>
<span class="line"><span style="color:#A6ACCD;">node -v </span><span style="color:#676E95;"># Should print &quot;v24.15.0&quot;.</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;"># \u9A8C\u8BC1 npm \u7248\u672C\uFF1A</span></span>
<span class="line"><span style="color:#A6ACCD;">npm -v </span><span style="color:#676E95;"># Should print &quot;11.12.1&quot;.</span></span>
<span class="line"></span></code></pre><div class="line-numbers-wrapper"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p>\u6267\u884C\u4E0A\u9762\u8FD9\u4E9B\u547D\u4EE4\u662F\u4E3A\u4E86\u5B89\u88C5\u5927\u6A21\u578B\u8FD0\u884C\u7684\u73AF\u5883, \u6709\u4E86\u8FD9\u4E9B\u73AF\u5883\u624D\u80FD\u6B63\u5E38\u542F\u52A8, \u6240\u4EE5\u8FD9\u4E00\u6B65\u662F\u5FC5\u4E0D\u53EF\u5C11\u7684</p><h2 id="_2-\u4E0B\u8F7D-codex-\u5BA2\u6237\u7AEF" tabindex="-1">2. \u4E0B\u8F7D Codex \u5BA2\u6237\u7AEF <a class="header-anchor" href="#_2-\u4E0B\u8F7D-codex-\u5BA2\u6237\u7AEF" aria-hidden="true">#</a></h2><blockquote><p>\u76EE\u524D\u4E3B\u6D41\u7684\u5927\u6A21\u578B\u5BA2\u6237\u7AEF\u6709: Claude/Codex/Opencode, \u5176\u4E2D\u53EA\u6709 Codex \u662F\u6709\u56FE\u5F62\u5316\u754C\u9762\u7684, \u4FBF\u4E8E\u65B0\u624B\u64CD\u4F5C(\u5F53\u7136\u5BF9\u8001\u624B\u4E5F\u4FBF\u6377\u{1F61C}), \u540C\u65F6 Codex \u66F4\u65B0\u901F\u5EA6\u5F88\u5FEB, GPT \u4E5F\u4FBF\u4E8E\u8BA2\u9605, \u6240\u4EE5\u4EE5\u8FD9\u4E2A\u4E3A\u6559\u7A0B.</p></blockquote><p>\u8BE5\u5BA2\u6237\u7AEF\u662FChat gpt \u5F00\u53D1\u7684\u4E13\u95E8\u7528\u4E8E\u7F16\u7A0B\u7684\u5BA2\u6237\u7AEF, \u4E0D\u8FC7\u9664\u4E86\u7F16\u7A0B, \u4E5F\u53EF\u4EE5\u7528\u4E8E\u54A8\u8BE2\u5176\u4ED6\u95EE\u9898, \u73B0\u5728\u66F4\u65B0\u540E\u8FD8\u80FD\u76F4\u63A5\u64CD\u4F5C\u4F60\u7684 Mac \u7535\u8111, \u4E00\u6761\u9F99\u670D\u52A1.</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki"><code><span class="line"><span style="color:#A6ACCD;">// \u6D4F\u89C8\u5668\u6253\u5F00\u6539\u94FE\u63A5, \u6B63\u5E38\u5B89\u88C5\u5373\u53EF</span></span>
<span class="line"><span style="color:#A6ACCD;">https://openai.com/codex/</span></span>
<span class="line"><span style="color:#A6ACCD;"></span></span></code></pre><div class="line-numbers-wrapper"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>\u8F6F\u4EF6\u5B89\u88C5\u5B8C\u6BD5\u540E, Codex\u6709\u4E24\u79CD\u767B\u5F55\u65B9\u5F0F, \u4E00\u79CD\u662F\u76F4\u63A5\u767B\u5F55GPT\u7684\u7F51\u9875, \u6388\u6743\u767B\u5F55; \u4E00\u79CD\u662F\u4F7F\u7528\u5BC6\u94A5, \u8FD9\u79CD\u4E00\u822C\u662F\u4E70\u4E86\u4E2D\u8F6C\u7AD9, \u6216\u8005\u516C\u53F8/\u81EA\u5DF1\u642D\u5EFA\u7684\u4E00\u4E9B\u5927\u6A21\u578B\u4E2D\u8F6C\u65F6\u7528. \u6211\u4EEC\u5927\u591A\u6570\u8FD8\u662F\u4F7F\u7528 GPT \u7684\u7F51\u9875\u8FDB\u884C\u6388\u6743\u767B\u5F55\u5373\u53EF.</p><h2 id="_3-codex-\u9875\u9762\u4ECB\u7ECD" tabindex="-1">3. Codex \u9875\u9762\u4ECB\u7ECD <a class="header-anchor" href="#_3-codex-\u9875\u9762\u4ECB\u7ECD" aria-hidden="true">#</a></h2><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20260423194619202.png" alt="image-20260423194619202"></p><p>\u767B\u5F55 Codex \u540E\u7684\u9875\u9762\u5982\u4E0A\u56FE\u6240\u793A (\u622A\u56FE\u662F\u5BC6\u94A5\u6388\u6743, \u6240\u4EE5\u4F1A\u6709\u7070\u8272\u83DC\u5355), \u56FE\u4E0A\u6807\u8BC6\u4EE3\u8868:</p><ol><li><p>\u9009\u62E9\u672C\u5730\u7684\u4E00\u4E2A\u6587\u4EF6\u5939, \u5F62\u6210\u4E00\u4E2A\u9879\u76EE(\u8FD9\u4E2A\u540D\u8BCD\u53EA\u662F\u540D\u8BCD, \u5176\u5B9E\u5B83\u8FD8\u662F\u6587\u4EF6\u5939, \u4EC0\u4E48\u90FD\u6CA1\u53D8), \u65B0\u5EFA\u804A\u6761\u7684\u65F6\u5019\u4FBF\u53EF\u4EE5\u9009\u62E9\u8FD9\u4E2A\u9879\u76EE(\u6587\u4EF6\u5939)\u4F5C\u4E3A\u5BF9\u8BDD\u7684\u4E0A\u4E0B\u6587\u5730\u5740, \u4F60\u53EF\u4EE5\u5728\u8FD9\u4E2A\u9879\u76EE\u4E0B\u7528\u81EA\u7136\u8BED\u8A00(\u5C31\u662F\u6B63\u5E38\u8BF4\u7684\u8BDD) \u6784\u5EFA\u81EA\u5DF1\u7684\u5E94\u7528</p></li><li><p>a. \u8FD9\u91CC\u6709\u4E00\u4E2A &quot;+&quot; \u7B26\u53F7, \u70B9\u51FB\u540E\u4F60\u53EF\u4EE5\u6DFB\u52A0\u56FE\u7247\u7B49, \u8FD8\u53EF\u4EE5\u8BBE\u7F6E&quot;\u8BA1\u5212&quot;\u6A21\u5F0F, \u5728\u6539\u6A21\u5F0F\u4E0B\u4F60\u7B80\u5355\u63D0\u4E00\u4E2A\u5C0F\u9700\u6C42, \u5982&quot;\u6211\u60F3\u8981\u65B0\u5EFA\u4E00\u4E2A\u7F51\u9875&quot;, \u4E0D\u5F00\u8BA1\u5212\u6A21\u5F0F\u7684\u8BDD\u5927\u6A21\u578B\u53EF\u80FDkuku \u5C31\u5F00\u5199\u4E86, \u5F00\u4E86&quot;\u8BA1\u5212&quot;\u6A21\u5F0F\u540E, \u5927\u6A21\u578B\u4F1A\u4E3B\u52A8\u601D\u8003\u4F60\u8FD9\u4E2A\u9700\u6C42, \u7136\u540E\u95EE\u4F60, \u662F\u4E0D\u662F\u9700\u8981\u517C\u5BB9\u624B\u673A\u7AEF\u4E5F\u6B63\u5E38\u663E\u793A\u8FD9\u79CD? \u8FD9\u4E2A\u6A21\u5F0F\u4E0B\u5B83\u4F1A\u60F3\u5230\u4E00\u4E9B\u4F60\u9057\u6F0F\u7684\u70B9, \u6240\u4EE5\u63A8\u8350\u5728\u9002\u5F53\u7684\u65F6\u5019\u6253\u5F00(\u6253\u5F00\u4F1A\u591A\u8D39\u4E00\u4E9B token).</p><p>b. \u65C1\u8FB9\u8FD8\u6709\u4E00\u4E2A\u5927\u6A21\u578B\u7684\u6743\u9650, \u8FD9\u91CC\u5EFA\u8BAE\u76F4\u63A5\u6253\u5F00 &quot;\u5B8C\u5168\u8BBF\u95EE\u6743\u9650&quot; \u5C31\u884C, \u5176\u4ED6\u6CA1\u4EC0\u4E48\u53EF\u8BF4\u7684</p></li><li><p>\u8FD9\u91CC\u5C31\u662F\u9009\u62E9\u5927\u6A21\u578B\u4E86, \u4E00\u822C\u4F7F\u7528 GPT-4 \u5C31\u884C, \u601D\u8003\u8BBE\u4E3A &quot;\u9AD8&quot; \u5373\u53EF.</p></li><li><p>\u8FD9\u91CC\u53EF\u4EE5\u5207\u6362\u4F60\u5BF9\u8BDD\u7684\u9879\u76EE, \u6BD4\u5982\u9879\u76EE A \u4F60\u662F\u505A\u4E00\u4E2A\u7F51\u9875, \u9879\u76EE B \u4F60\u662F\u505A\u4E00\u4E2A APP, \u90A3\u4E48\u4F60\u5728\u9879\u76EE A \u4E0B\u9762\u95EE\u9879\u76EE B \u7684\u4E8B\u60C5, \u90A3\u80AF\u5B9A\u5C31\u95EE\u4E0D\u51FA\u6765, \u6240\u4EE5\u8FD9\u5C31\u662F\u9879\u76EE\u7684\u610F\u4E49, \u533A\u5206\u4E0D\u540C\u7684\u5DE5\u4F5C\u7A7A\u95F4. \u540E\u9762\u4E24\u4E2A\u9009\u9879\u7B2C\u4E00\u4E2A\u76F4\u63A5\u9009\u62E9\u672C\u5730\u5C31\u884C, \u4E0D\u7528\u7BA1; \u53E6\u4E00\u4E2A\u4E5F\u662F\u5F3A\u5F00\u53D1\u76F8\u5173\u7684, \u4E5F\u53EF\u4EE5\u6682\u65F6\u5148\u4E0D\u7528\u7BA1, \u5148\u628A\u81EA\u5DF1\u60F3\u8981\u5B9E\u73B0\u7684\u9879\u76EE\u5B8C\u6210\u5C31\u53EF\u4EE5.</p></li></ol><h2 id="_4-\u6784\u5EFA\u81EA\u5DF1\u7684\u9879\u76EE" tabindex="-1">4. \u6784\u5EFA\u81EA\u5DF1\u7684\u9879\u76EE <a class="header-anchor" href="#_4-\u6784\u5EFA\u81EA\u5DF1\u7684\u9879\u76EE" aria-hidden="true">#</a></h2><p>\u770B\u5B8C\u4E0A\u9762\u7B2C 3 \u90E8\u5206, \u4F60\u5E94\u8BE5\u5C31\u521B\u5EFA\u597D\u81EA\u5DF1\u7684\u9879\u76EE\u4E86, \u7136\u540E\u4F60\u5C31\u53EF\u4EE5\u5F00\u59CB\u4F60\u7684 Vibe Coding (\u6C1B\u56F4\u7F16\u7A0B, \u5176\u5B9E\u5C31\u662F\u4F60\u8BF4\u8BDD, \u4ED6\u5E72\u6D3B...)\u4E86.\u5982\u4E0B\u6240\u793A:</p><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20260423195318097.png" alt="image-20260423195318097"></p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki"><code><span class="line"><span style="color:#A6ACCD;">//\u63D0\u793A\u8BED</span></span>
<span class="line"><span style="color:#A6ACCD;">\u6211\u60F3\u8981\u642D\u5EFA\u4E00\u4E2A\u7F51\u7AD9, \u8BE5\u7F51\u7AD9\u53EF\u4EE5\u8BA9\u6211\u5217\u51FA\u6765\u6BCF\u65E5 TODO \u4E8B\u4EF6,\u5F53\u6211\u5B8C\u6210\u4E00\u4E2A\u4E8B\u4EF6\u540E, \u70B9\u51FB\u540E\u8BE5\u4E8B\u4EF6\u5C31\u53EF\u4EE5\u81EA\u52A8\u5F52\u5E76\u5230\u5DF2\u5B8C\u6210; \u5982\u679C\u5F53\u5929\u4E8B\u4EF6\u6CA1\u6709\u5B8C\u6210, \u90A3\u4E48\u8BE5\u4E8B\u4EF6\u81EA\u52A8\u987A\u79FB\u5230\u7B2C\u4E8C\u5929.</span></span>
<span class="line"><span style="color:#A6ACCD;"></span></span></code></pre><div class="line-numbers-wrapper"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>\u53EF\u4EE5\u770B\u5230, \u6211\u7684\u63D0\u793A\u8BCD\u662F\u5F88\u7B80\u5355\u7684, \u80AF\u5B9A\u4F1A\u6709\u5F88\u591A\u9057\u6F0F\u7684\u4E1C\u897F, \u4F46\u662F\u5728\u4E0A\u9762\u6211<strong>\u6253\u5F00\u4E86\u8BA1\u5212\u6A21\u5F0F</strong>, \u8FD9\u6837\u5927\u6A21\u578B\u5C31\u4F1A\u81EA\u52A8\u5E2E\u6211\u53BB\u8003\u8651\u5176\u4ED6\u573A\u666F, \u9010\u6B65\u5B8C\u5584\u8FD9\u4E2A\u65B9\u6848.</p><p>\u5927\u6A21\u578B\u5982\u679C\u5B9E\u73B0\u5B8C\u6BD5\u540E, \u4E00\u822C\u4F1A\u544A\u8BC9\u4F60\u5982\u4F55\u6253\u5F00\u8FD9\u4E2A\u9879\u76EE\u770B\u6548\u679C; \u5982\u679C\u4ED6\u6CA1\u6709\u544A\u8BC9\u4F60, \u90A3\u4E48\u4F60\u5C31\u53EF\u4EE5\u76F4\u63A5\u5728\u5BF9\u8BDD\u6846\u4E2D\u95EE\u5B83: \u6211\u600E\u4E48\u770B\u5230\u6548\u679C? \u8FD9\u5C31\u662F\u6C1B\u56F4\u7F16\u7A0B, \u4F60\u53EA\u7BA1\u6307\u6325\u5C31\u884C.</p><p><strong>\u9700\u8981\u6CE8\u610F</strong>, \u5F53\u4F60\u5728\u4E00\u4E2A\u804A\u5929\u5185\u53D1\u8D77\u4E00\u4E2A\u5BF9\u8BDD\u540E, \u804A\u5929\u6846\u4F1A\u591A\u51FA\u6765\u4E00\u4E2A\u80CC\u666F\u4FE1\u606F\u7A97\u53E3\u7684\u5C0F\u56FE\u6807, \u9F20\u6807\u653E\u4E0A\u53BB\u53EF\u4EE5\u770B\u5230\u5F53\u524D\u7A97\u53E3\u4F7F\u7528\u4E86\u591A\u5C11. \u4F60\u53EF\u4EE5\u628A\u8BE5\u7A97\u53E3\u5F53\u505A\u5927\u6A21\u578B\u7684\u8111\u5BB9\u91CF, \u4F60\u5728\u8FD9\u4E2A\u804A\u5929\u5185\u548C\u5B83\u804A\u7684\u95EE\u9898\u6B21\u6570\u548C\u590D\u6742\u5EA6\u90FD\u4F1A\u7D2F\u8BA1\u5230\u7A97\u53E3\u5360\u7528\u4E2D, \u5F53\u5360\u7528\u5FEB\u6EE1 ( 100% ) \u7684\u65F6\u5019\u53EF\u4EE5\u7B80\u5355\u7406\u89E3\u4E3A\u5B83\u5FEB\u8981\u8111\u5B50\u4E0D\u6E05\u695A, \u5F00\u59CB\u80E1\u8BF4\u4E86, \u6240\u4EE5\u8FD9\u4E2A\u65F6\u5019\u8981\u65B0\u5F00\u4E00\u4E2A\u804A\u5929\u7A97\u53E3, \u7EE7\u7EED\u4F60\u6CA1\u6709\u5B8C\u6210\u7684\u4EFB\u52A1.</p><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20260423195642773.png" alt="image-20260423195642773"></p>`,23),o=[p];function t(c,i,r,d,u,b){return n(),a("div",null,o)}const C=s(l,[["render",t]]);export{m as __pageData,C as default};
